package com.jyfq.loan.thirdparty.model;

import com.alibaba.fastjson2.annotation.JSONField;
import com.fasterxml.jackson.annotation.JsonIgnore;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.math.BigDecimal;
import java.util.List;
import java.util.Map;

/**
 * Pre-check result.
 */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class PreCheckResult {

    /** Whether the pre-check passed. */
    private boolean pass;

    /** Real-time price / settlement price. */
    private BigDecimal price;

    /** Downstream returned price. */
    private BigDecimal downstreamPrice;

    /** Downstream price multiplied by product price ratio. */
    private BigDecimal productCoefficientPrice;

    /** Product coefficient price multiplied by channel fee rate. */
    private BigDecimal upstreamChannelPrice;

    /** Third-party request id / uuid. */
    private String uuid;

    /** Third-party order id. */
    private String orderId;

    /** Downstream product logo. */
    private String productLogo;

    /** Product name for frontend display. */
    private String productName;

    /** Downstream company name. */
    private String companyName;

    /** Downstream protocol list. */
    private List<Map<String, Object>> protocolList;

    /** Number of matched masked mobile MD5 values returned by downstream. */
    private Integer matchSize;

    /** Matched mobile MD5 values returned by downstream. */
    private List<String> mobileList;

    /** Product id. */
    private Long productId;

    /** Institution id. */
    private Long instId;

    /** Institution code. */
    private String instCode;

    /** Institution name for frontend display. */
    private String instName;

    /** Local order number generated by this system. */
    private String localOrderNo;

    /** Reject reason when not passed. */
    private String rejectReason;

    /** Product results that passed the H5 pre-check, ordered for frontend rendering. */
    private List<PreCheckResult> products;

    /** Downstream pre-check request payload for audit/search. */
    @JsonIgnore
    @JSONField(serialize = false)
    private String requestLog;

    /** Downstream pre-check response payload for audit/search. */
    @JsonIgnore
    @JSONField(serialize = false)
    private String responseLog;
}
